cqop:CadQueryOperationOntology a owl:Ontology ;
    dcterms:title "CadQuery Operation Ontology" ;
    owl:versionInfo "1.2.0" ;
    dcterms:created "2026-08-19"^^xsd:date ;
    dcterms:modified "2026-08-19"^^xsd:date ;
    dcterms:description "Curated operation-level ontology for generalizable feature creation and editing in CadQuery; not an exhaustive mirror of every CadQuery Python method or OpenCascade function." ;
    cqop:compatibility "CadQuery latest official documentation accessed 2026-08-19; templates target the CadQuery 2.x-style Workplane, Sketch, Shape, and Assembly APIs documented there." ;
    cqop:namingPattern "DoActiontoGeometry" ;
    cqop:parameterPolicyJson "{\"excluded_from_parameters\": \"Design intentions such as reduce weight, improve grip, increase stiffness, or look realistic are not executable CadQuery parameters.\", \"optional_parameters\": \"CadQuery flags with safe defaults or variant-only inputs are separated into optional_parameters.\", \"required_parameters\": \"Only information needed to deterministically resolve references, placement, dimensions, and extent is placed in required_parameters.\", \"units\": \"CadQuery model values are unitless; this ontology assumes a project-wide model length unit, conventionally millimetres.\"}" .

