cqop:CreateBoxtoWorkplane a cqop:CadQueryOperation, cqop:AdditiveFeatureOperation ;
    schema:name "CreateBoxtoWorkplane" ;
    rdfs:label "create box" ;
    dcterms:description "Create a rectangular prismatic solid at a workplane." ;
    cqop:family cqop:AdditiveFeatureOperation ;
    cqop:action "create box" ;
    cqop:referenceGeometry "Workplane" ;
    cqop:implementationKind "direct" ;
    cqop:pythonTemplate "result = cq.Workplane(workplane).box(length, width, height)" ;
    cqop:effectMaterialChange "add" ;
    cqop:effectReturns "CadQuery Workplane, Shape, or Assembly containing the operation result" ;
    cqop:cadqueryMethod "Workplane" ;
    cqop:cadqueryMethod "Workplane.box" ;
    cqop:requiredParameter cqop:param_CreateBoxtoWorkplane_workplane ;
    cqop:requiredParameter cqop:param_CreateBoxtoWorkplane_length ;
    cqop:requiredParameter cqop:param_CreateBoxtoWorkplane_width ;
    cqop:requiredParameter cqop:param_CreateBoxtoWorkplane_height ;
    cqop:optionalParameter cqop:param_CreateBoxtoWorkplane_centered ;
    cqop:optionalParameter cqop:param_CreateBoxtoWorkplane_combine .

cqop:param_CreateBoxtoWorkplane_workplane a cqop:RequiredParameter, cqop:PlaneReference ;
    schema:name "workplane" ;
