cqop:ExtendBodytoFace a cqop:CadQueryOperation, cqop:AdditiveFeatureOperation ;
    schema:name "ExtendBodytoFace" ;
    rdfs:label "extend body" ;
    dcterms:description "Extend a planar end face along its outward normal while preserving the complete face section, including inner loops." ;
