    cqop:action "extend body" ;
    cqop:referenceGeometry "Face" ;
    cqop:implementationKind "composite" ;
    cqop:pythonTemplate "extension_vector = end_face.normalAt().multiply(extension_distance)\nextension_solid = cq.Solid.extrudeLinear(\n    end_face.outerWire(), end_face.innerWires(), extension_vector\n)\nresult = target_body.union(cq.Workplane(obj=extension_solid))" ;
    cqop:effectMaterialChange "add" ;
    cqop:effectReturns "CadQuery Workplane, Shape, or Assembly containing the operation result" ;
    cqop:cadqueryMethod "Face.normalAt" ;
    cqop:cadqueryMethod "Face.outerWire" ;
    cqop:cadqueryMethod "Face.innerWires" ;
    cqop:cadqueryMethod "Solid.extrudeLinear" ;
    cqop:cadqueryMethod "Workplane.union" ;
    cqop:precondition "end_face is planar, terminal, and has the intended outward normal." ;
    cqop:precondition "A simple section continuation is valid; helical threads or other changing longitudinal detail must be rebuilt separately." ;
    cqop:note "Use TrimBodytoPlane for shortening rather than supplying a negative extension distance." ;
    cqop:requiredParameter cqop:param_ExtendBodytoFace_target_body ;
    cqop:requiredParameter cqop:param_ExtendBodytoFace_end_face ;
    cqop:requiredParameter cqop:param_ExtendBodytoFace_extension_distance .

