cqop:CreateOffsetExtrusiontoWire a cqop:CadQueryOperation, cqop:AdditiveFeatureOperation ;
    schema:name "CreateOffsetExtrusiontoWire" ;
    rdfs:label "create offset extrusion" ;
    dcterms:description "Create an all-around flange, rim, or supporting step between a closed planar boundary wire and its offset, then extrude that annular region." ;
    cqop:family cqop:AdditiveFeatureOperation ;
    cqop:action "create offset extrusion" ;
    cqop:referenceGeometry "Wire" ;
    cqop:implementationKind "composite" ;
    cqop:pythonTemplate "offset_wire = boundary_wire.offset2D(offset_distance, kind=corner_kind)[0]\nouter_wire = offset_wire if offset_side == 'outside' else boundary_wire\ninner_wire = boundary_wire if offset_side == 'outside' else offset_wire\noffset_solid = cq.Solid.extrudeLinear(outer_wire, [inner_wire], extrusion_vector)\nresult = target_body.union(cq.Workplane(obj=offset_solid))" ;
    cqop:effectMaterialChange "add" ;
    cqop:effectReturns "CadQuery Workplane, Shape, or Assembly containing the operation result" ;
    cqop:cadqueryMethod "Wire.offset2D" ;
    cqop:cadqueryMethod "Solid.extrudeLinear" ;
    cqop:cadqueryMethod "Workplane.union" ;
    cqop:precondition "boundary_wire is closed, planar, and produces exactly one non-self-intersecting offset wire." ;
    cqop:precondition "outer_wire encloses inner_wire and the extruded region intersects the target body." ;
    cqop:note "This operation intentionally leaves the central region unfilled and covers general flanges, rims, and bottom support steps." ;
    cqop:requiredParameter cqop:param_CreateOffsetExtrusiontoWire_target_body ;
    cqop:requiredParameter cqop:param_CreateOffsetExtrusiontoWire_boundary_wire ;
    cqop:requiredParameter cqop:param_CreateOffsetExtrusiontoWire_offset_distance ;
    cqop:requiredParameter cqop:param_CreateOffsetExtrusiontoWire_offset_side ;
    cqop:requiredParameter cqop:param_CreateOffsetExtrusiontoWire_extrusion_vector ;
    cqop:optionalParameter cqop:param_CreateOffsetExtrusiontoWire_corner_kind .

cqop:param_CreateOffsetExtrusiontoWire_target_body a cqop:RequiredParameter, cqop:BodyReference ;
    schema:name "target_body" ;
