    cqop:pythonTemplate "slot = (target_body.newObject([target_face]).workplane()\n        .pushPoints(locations).slot2D(slot_length, slot_width, slot_angle))\nresult = slot.cutThruAll() if cut_extent == 'through_all' else slot.cutBlind(cut_extent)" ;
