    cqop:cadqueryMethod "Workplane.cutBlind" ;
    cqop:cadqueryMethod "Workplane.cutThruAll" ;
    cqop:precondition "slot_length >= slot_width > 0." ;
    cqop:requiredParameter cqop:param_CreateSlotCuttoFace_target_body ;
    cqop:requiredParameter cqop:param_CreateSlotCuttoFace_target_face ;
    cqop:requiredParameter cqop:param_CreateSlotCuttoFace_locations ;
    cqop:requiredParameter cqop:param_CreateSlotCuttoFace_slot_length ;
    cqop:requiredParameter cqop:param_CreateSlotCuttoFace_slot_width ;
    cqop:requiredParameter cqop:param_CreateSlotCuttoFace_slot_angle ;
