    cqop:requiredParameter cqop:param_CreatePolygonCuttoFace_locations ;
    cqop:requiredParameter cqop:param_CreatePolygonCuttoFace_circumradius ;
    cqop:requiredParameter cqop:param_CreatePolygonCuttoFace_side_count ;
    cqop:requiredParameter cqop:param_CreatePolygonCuttoFace_rotation_angle ;
