    schema:name "ChangeHoleDiametertoHole" ;
    rdfs:label "change hole diameter" ;
    dcterms:description "Replace a cylindrical hole diameter by restoring the old void and cutting a new coaxial cylinder." ;
    cqop:family cqop:FeatureModificationRepairOperation ;
    cqop:action "change hole diameter" ;
    cqop:referenceGeometry "Hole" ;
    cqop:implementationKind "repair" ;
    cqop:pythonTemplate "axis_plane = cq.Plane(origin=hole_center, normal=hole_axis)\nold_plug = cq.Workplane(axis_plane).circle(existing_diameter / 2).extrude(repair_length / 2, both=True, combine=False)\nrestored = target_body.union(old_plug)\nnew_tool = cq.Workplane(axis_plane).circle(new_diameter / 2).extrude(repair_length / 2, both=True, combine=False)\nresult = restored.cut(new_tool)" ;
    cqop:effectMaterialChange "mixed" ;
